// Package main is the entry point for the AI.YOU CLI application.
package main

import (
	"context"
	"os"
	"os/signal"
	"syscall"

	"github.com/chrlesur/aiyou.cli/internal/cli"
	"github.com/chrlesur/aiyou.cli/internal/config"
	"github.com/sirupsen/logrus"
)

// main initializes and starts the AI.YOU CLI application.
// It handles graceful shutdown and proper error management.
func main() {
	// Create context with cancellation for graceful shutdown
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	// Initialize configuration
	cfg, err := config.Load()
	if err != nil {
		logrus.Fatalf("Failed to load configuration: %v", err)
	}

	// Initialize logger
	logger := cli.NewLogger(cfg.LogLevel)
	logger.Info("Starting AI.YOU CLI")

	// Setup signal handling for graceful shutdown
	sigChan := make(chan os.Signal, 1)
	signal.Notify(sigChan, syscall.SIGINT, syscall.SIGTERM)

	// Initialize CLI application
	app, err := cli.NewApp(cfg, logger)
	if err != nil {
		logger.Fatalf("Failed to initialize CLI application: %v", err)
	}

	// Start the application
	go func() {
		if err := app.Run(ctx); err != nil {
			logger.Errorf("Application error: %v", err)
			cancel()
		}
	}()

	// Wait for shutdown signal
	<-sigChan
	logger.Info("Shutting down gracefully...")
	cancel()
}

// internal/cache/example_test.go
package cache_test

import (
	"context"
	"fmt"
	"log"
	"time"

	"github.com/chrlesur/aiyou.cli/internal/cache"
	"github.com/chrlesur/aiyou.cli/internal/cache/memory"
)

func Example() {
	// Création d'un nouveau cache avec la configuration par défaut
	config := cache.DefaultConfig()
	c, err := memory.NewMemoryCache(config)
	if err != nil {
		log.Fatal(err)
	}
	defer c.Close()

	ctx := context.Background()

	// Stockage d'une valeur
	err = c.Set(ctx, "greeting", "Hello, World!", cache.QueryCache)
	if err != nil {
		log.Fatal(err)
	}

	// Récupération de la valeur
	entry, exists := c.Get(ctx, "greeting")
	if exists {
		fmt.Println(entry.Value)
	}
	// Output: Hello, World!
}

func Example_withExpiration() {
	config := cache.DefaultConfig()
	config.QueryTTL = 1 * time.Second
	c, _ := memory.NewMemoryCache(config)
	defer c.Close()

	ctx := context.Background()

	c.Set(ctx, "temp", "temporary value", cache.QueryCache)

	entry, exists := c.Get(ctx, "temp")
	fmt.Printf("Immediately: %v\n", exists)

	time.Sleep(2 * time.Second)

	entry, exists = c.Get(ctx, "temp")
	fmt.Printf("After expiration: %v\n", exists)

	// Output:
	// Immediately: true
	// After expiration: false
}

// Package api provides the core API interaction layer for the AI.YOU CLI
package api

import (
	"context"
	"errors"
	"fmt"
	"sync"
	"time"

	"github.com/chrlesur/aiyou.cli/internal/config"
	"github.com/chrlesur/aiyou.golib"
)

var (
	// ErrNotAuthenticated is returned when an operation requires authentication
	ErrNotAuthenticated = errors.New("not authenticated")
	// ErrInvalidCredentials is returned when login fails
	ErrInvalidCredentials = errors.New("invalid credentials")
	// ErrTokenExpired is returned when the current token has expired
	ErrTokenExpired = errors.New("token expired")
)

// AuthManager handles all authentication-related operations including
// token management and session state.
type AuthManager struct {
	mu     sync.RWMutex
	client *aiyou.Client
	cfg    *config.Config
	token  string
	expiry time.Time
}

// NewAuthManager creates a new authentication manager with the provided client and configuration.
// It initializes with default settings for token refresh behavior.
func NewAuthManager(client *aiyou.Client, cfg *config.Config) (*AuthManager, error) {
	if client == nil {
		return nil, errors.New("client is required")
	}
	if cfg == nil {
		return nil, errors.New("config is required")
	}

	return &AuthManager{
		client: client,
		cfg:    cfg,
	}, nil
}

// Login authenticates a user with the provided email and password.
// It returns an error if authentication fails or if the API is unavailable.
func (a *AuthManager) Login(ctx context.Context, email, password string) error {
	if ctx == nil {
		return errors.New("context is required")
	}
	if email == "" || password == "" {
		return errors.New("email and password are required")
	}

	// Create a new client with authentication
	client, err := aiyou.NewClient(email, password)
	if err != nil {
		if err.Error() == "invalid credentials" {
			return ErrInvalidCredentials
		}
		return fmt.Errorf("authentication failed: %w", err)
	}

	// Update internal state with new client
	a.mu.Lock()
	defer a.mu.Unlock()

	a.client = client
	a.expiry = time.Now().Add(24 * time.Hour)
	return nil
}

// GetToken returns the current authentication token.
// It returns an error if not authenticated.
func (a *AuthManager) GetToken(ctx context.Context) (string, error) {
	if ctx == nil {
		return "", errors.New("context is required")
	}

	a.mu.RLock()
	defer a.mu.RUnlock()

	if a.client == nil {
		return "", ErrNotAuthenticated
	}

	// Vérifier que le token n'a pas expiré
	if time.Now().After(a.expiry) {
		return "", ErrTokenExpired
	}

	return a.token, nil
}

// IsAuthenticated returns true if there is a valid authentication session.
func (a *AuthManager) IsAuthenticated() bool {
	a.mu.RLock()
	defer a.mu.RUnlock()

	return a.client != nil && time.Now().Before(a.expiry)
}

// Logout removes the current authentication session.
// It returns an error if the logout operation fails.
func (a *AuthManager) Logout() error {
	a.mu.Lock()
	defer a.mu.Unlock()

	if a.client == nil {
		return nil // Already logged out
	}

	// Reset all authentication state
	a.client = nil
	a.token = ""
	a.expiry = time.Time{}

	return nil
}

package api

import (
	"context"
	"testing"
	"time"

	"github.com/chrlesur/aiyou.cli/internal/config"
	"github.com/chrlesur/aiyou.golib"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func TestNewAuthManager(t *testing.T) {
	tests := []struct {
		name    string
		client  *aiyou.Client
		cfg     *config.Config
		wantErr bool
	}{
		{
			name:    "success with valid inputs",
			client:  &aiyou.Client{},
			cfg:     &config.Config{},
			wantErr: false,
		},
		{
			name:    "error with nil client",
			client:  nil,
			cfg:     &config.Config{},
			wantErr: true,
		},
		{
			name:    "error with nil config",
			client:  &aiyou.Client{},
			cfg:     nil,
			wantErr: true,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			manager, err := NewAuthManager(tt.client, tt.cfg)
			if tt.wantErr {
				assert.Error(t, err)
				assert.Nil(t, manager)
			} else {
				assert.NoError(t, err)
				assert.NotNil(t, manager)
			}
		})
	}
}

func TestAuthManager_Login(t *testing.T) {
	cfg := &config.Config{}
	validEmail := "test@example.com"
	validPassword := "password123"

	tests := []struct {
		name     string
		email    string
		password string
		setup    func(*testing.T) *aiyou.Client
		wantErr  bool
	}{
		{
			name:     "successful login",
			email:    validEmail,
			password: validPassword,
			setup: func(t *testing.T) *aiyou.Client {
				return &aiyou.Client{}
			},
			wantErr: false,
		},
		{
			name:     "empty email",
			email:    "",
			password: validPassword,
			setup: func(t *testing.T) *aiyou.Client {
				return &aiyou.Client{}
			},
			wantErr: true,
		},
		{
			name:     "empty password",
			email:    validEmail,
			password: "",
			setup: func(t *testing.T) *aiyou.Client {
				return &aiyou.Client{}
			},
			wantErr: true,
		},
		{
			name:     "nil context",
			email:    validEmail,
			password: validPassword,
			setup: func(t *testing.T) *aiyou.Client {
				return &aiyou.Client{}
			},
			wantErr: true,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			client := tt.setup(t)
			manager, err := NewAuthManager(client, cfg)
			require.NoError(t, err)

			ctx := context.Background()
			if tt.name == "nil context" {
				ctx = nil
			}

			err = manager.Login(ctx, tt.email, tt.password)
			if tt.wantErr {
				assert.Error(t, err)
			} else {
				assert.NoError(t, err)
				assert.True(t, manager.IsAuthenticated())
			}
		})
	}
}

func TestAuthManager_Logout(t *testing.T) {
	cfg := &config.Config{}
	client := &aiyou.Client{}

	tests := []struct {
		name    string
		setup   func(*AuthManager)
		wantErr bool
	}{
		{
			name: "successful logout when logged in",
			setup: func(am *AuthManager) {
				ctx := context.Background()
				_ = am.Login(ctx, "test@example.com", "password123")
			},
			wantErr: false,
		},
		{
			name: "successful logout when not logged in",
			setup: func(am *AuthManager) {
				// No setup needed - already logged out
			},
			wantErr: false,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			manager, err := NewAuthManager(client, cfg)
			require.NoError(t, err)

			if tt.setup != nil {
				tt.setup(manager)
			}

			err = manager.Logout()
			if tt.wantErr {
				assert.Error(t, err)
			} else {
				assert.NoError(t, err)
				assert.False(t, manager.IsAuthenticated())
			}
		})
	}
}

func TestAuthManager_GetToken(t *testing.T) {
	cfg := &config.Config{}
	client := &aiyou.Client{}

	tests := []struct {
		name      string
		setup     func(*AuthManager)
		wantErr   bool
		wantToken string
	}{
		{
			name: "get token when authenticated",
			setup: func(am *AuthManager) {
				ctx := context.Background()
				_ = am.Login(ctx, "test@example.com", "password123")
				// Simuler un token valide
				am.mu.Lock()
				am.token = "test-token"
				am.mu.Unlock()
			},
			wantErr:   false,
			wantToken: "test-token",
		},
		{
			name: "error when not authenticated",
			setup: func(am *AuthManager) {
				// No setup - not authenticated
			},
			wantErr:   true,
			wantToken: "",
		},
		{
			name: "error when token expired",
			setup: func(am *AuthManager) {
				ctx := context.Background()
				_ = am.Login(ctx, "test@example.com", "password123")
				am.mu.Lock()
				am.token = "expired-token"
				am.expiry = time.Now().Add(-1 * time.Hour) // Expired token
				am.mu.Unlock()
			},
			wantErr:   true,
			wantToken: "",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			manager, err := NewAuthManager(client, cfg)
			require.NoError(t, err)

			if tt.setup != nil {
				tt.setup(manager)
			}

			ctx := context.Background()
			token, err := manager.GetToken(ctx)
			if tt.wantErr {
				assert.Error(t, err)
				assert.Empty(t, token)
			} else {
				assert.NoError(t, err)
				assert.Equal(t, tt.wantToken, token)
			}
		})
	}
}

func TestAuthManager_IsAuthenticated(t *testing.T) {
	cfg := &config.Config{}
	client := &aiyou.Client{}

	tests := []struct {
		name       string
		setup      func(*AuthManager)
		expectAuth bool
	}{
		{
			name: "authenticated with valid token",
			setup: func(am *AuthManager) {
				ctx := context.Background()
				_ = am.Login(ctx, "test@example.com", "password123")
			},
			expectAuth: true,
		},
		{
			name: "not authenticated",
			setup: func(am *AuthManager) {
				// No setup needed
			},
			expectAuth: false,
		},
		{
			name: "expired token",
			setup: func(am *AuthManager) {
				ctx := context.Background()
				_ = am.Login(ctx, "test@example.com", "password123")
				am.expiry = time.Now().Add(-1 * time.Hour)
			},
			expectAuth: false,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			manager, err := NewAuthManager(client, cfg)
			require.NoError(t, err)

			if tt.setup != nil {
				tt.setup(manager)
			}

			assert.Equal(t, tt.expectAuth, manager.IsAuthenticated())
		})
	}
}

func TestAuthManager_ConcurrentAccess(t *testing.T) {
	cfg := &config.Config{}
	client := &aiyou.Client{}
	manager, err := NewAuthManager(client, cfg)
	require.NoError(t, err)

	// Test concurrent login/logout operations
	done := make(chan bool)
	go func() {
		ctx := context.Background()
		_ = manager.Login(ctx, "test@example.com", "password123")
		done <- true
	}()

	go func() {
		_ = manager.Logout()
		done <- true
	}()

	// Wait for both goroutines to complete
	<-done
	<-done

	// No assertions needed - we're just verifying that there are no race conditions
}

// internal/cache/doc.go

// Package cache fournit une solution de mise en cache pour l'application AI.YOU CLI.
//
// # Architecture
//
// Le package est organisé autour d'une interface Cache centrale qui définit
// les opérations standard de cache. L'implémentation actuelle (memoryCache)
// fournit un stockage en mémoire avec :
// - Gestion automatique de l'expiration des entrées
// - Support de différents types de données avec TTL configurables
// - Métriques et statistiques d'utilisation
// - Thread-safety pour les accès concurrents
//
// Utilisation
//
//	// Création d'un nouveau cache avec la configuration par défaut
//	config := cache.DefaultConfig()
//	cache, err := memory.NewMemoryCache(config)
//	if err != nil {
//		log.Fatal(err)
//	}
//	defer cache.Close()
//
//	// Stockage d'une valeur
//	err = cache.Set(ctx, "key", "value", cache.QueryCache)
//
//	// Récupération d'une valeur
//	entry, exists := cache.Get(ctx, "key")
//
// # Configuration
//
// Le cache peut être configuré via la structure CacheConfig qui permet de définir :
// - Les durées de vie (TTL) pour chaque type de données
// - La taille maximale du cache
// - L'intervalle de nettoyage des entrées expirées
//
// # Monitoring
//
// Le cache fournit des statistiques d'utilisation via la méthode GetStats :
// - Nombre d'entrées
// - Taille totale utilisée
// - Taux de succès/échecs
//
// # Thread-Safety
//
// Toutes les opérations du cache sont thread-safe et peuvent être utilisées
// en toute sécurité depuis plusieurs goroutines.
package cache

// Package memory fournit une implémentation en mémoire du système de cache.
// Cette implémentation est thread-safe et gère automatiquement l'expiration des entrées.
package memory

import (
	"context"
	"fmt"
	"sync"
	"time"

	"github.com/chrlesur/aiyou.cli/internal/cache"
)

// memoryCache implémente l'interface cache.Cache avec un stockage en mémoire.
// Elle utilise une map pour stocker les données et assure la thread-safety via mutex.
type memoryCache struct {
	// mu protège l'accès concurrent aux données du cache
	mu sync.RWMutex

	// items stocke les entrées du cache avec leur clé associée
	items map[string]cache.CacheEntry

	// config contient les paramètres de configuration du cache
	config cache.CacheConfig

	// stats maintient les statistiques d'utilisation du cache
	stats cache.CacheStats

	// stopChan est utilisé pour signaler l'arrêt de la routine de nettoyage
	stopChan chan struct{}
}

// NewMemoryCache crée et initialise une nouvelle instance de cache en mémoire.
// Il démarre également la routine de nettoyage automatique des entrées expirées.
//
// Paramètres :
// - config: Configuration du cache définissant les TTL et autres paramètres
//
// Retourne :
// - Une instance de Cache
// - Une erreur si l'initialisation échoue
func NewMemoryCache(config cache.CacheConfig) (cache.Cache, error) {
	mc := &memoryCache{
		items:    make(map[string]cache.CacheEntry),
		config:   config,
		stopChan: make(chan struct{}),
	}

	// Démarrage de la routine de nettoyage en arrière-plan
	go mc.startCleanup()

	return mc, nil
}

// Set ajoute ou met à jour une entrée dans le cache.
//
// Paramètres :
// - ctx: Contexte pour la gestion de l'annulation
// - key: Clé unique identifiant l'entrée
// - value: Valeur à mettre en cache
// - cacheType: Type de l'entrée déterminant sa durée de vie
//
// Retourne une erreur si :
// - Le contexte est annulé
// - La clé est invalide
// - La taille maximale du cache serait dépassée
func (m *memoryCache) Set(ctx context.Context, key string, value interface{}, cacheType cache.CacheType) error {
	// Vérification du contexte
	if err := ctx.Err(); err != nil {
		return fmt.Errorf("context error in Set: %w", err)
	}

	// Validation de la clé
	if key == "" {
		return cache.ErrCacheKeyInvalid
	}

	m.mu.Lock()
	defer m.mu.Unlock()

	// Calcul de la taille de la nouvelle entrée
	size, err := calculateSize(value)
	if err != nil {
		return fmt.Errorf("failed to calculate entry size: %w", err)
	}

	// Vérification de la limite de taille
	if m.stats.Size+size > m.config.MaxSize {
		return cache.ErrCacheFull
	}

	// Détermination du TTL selon le type
	ttl := m.getTTLForType(cacheType)

	// Création de l'entrée
	entry := cache.CacheEntry{
		Value:      value,
		Expiration: time.Now().Add(ttl),
		Type:       cacheType,
		Size:       size,
		CreatedAt:  time.Now(),
		LastAccess: time.Now(),
	}

	// Mise à jour du cache et des statistiques
	m.items[key] = entry
	m.updateStats(size, true)

	return nil
}

// Get récupère une entrée du cache.
//
// Paramètres :
// - ctx: Contexte pour la gestion de l'annulation
// - key: Clé de l'entrée à récupérer
//
// Retourne :
// - L'entrée trouvée
// - Un booléen indiquant si l'entrée existe et n'est pas expirée
func (m *memoryCache) Get(ctx context.Context, key string) (cache.CacheEntry, bool) {
	if err := ctx.Err(); err != nil {
		return cache.CacheEntry{}, false
	}

	m.mu.Lock() // Changé de RLock à Lock car nous modifions les stats
	defer m.mu.Unlock()

	entry, exists := m.items[key]
	if !exists {
		m.stats.MissCount++
		return cache.CacheEntry{}, false
	}

	// Vérification de l'expiration
	if time.Now().After(entry.Expiration) {
		m.stats.MissCount++
		delete(m.items, key) // Nettoyage de l'entrée expirée
		return cache.CacheEntry{}, false
	}

	// Mise à jour du dernier accès et des statistiques
	entry.LastAccess = time.Now()
	m.items[key] = entry
	m.stats.HitCount++

	return entry, true
}

// Delete supprime une entrée du cache.
//
// Paramètres :
// - ctx: Contexte pour la gestion de l'annulation
// - key: Clé de l'entrée à supprimer
//
// Retourne une erreur si le contexte est annulé
func (m *memoryCache) Delete(ctx context.Context, key string) error {
	if err := ctx.Err(); err != nil {
		return fmt.Errorf("context error in Delete: %w", err)
	}

	m.mu.Lock()
	defer m.mu.Unlock()

	if entry, exists := m.items[key]; exists {
		m.updateStats(entry.Size, false)
		delete(m.items, key)
	}

	return nil
}

// Clear supprime toutes les entrées du cache.
//
// Paramètres :
// - ctx: Contexte pour la gestion de l'annulation
//
// Retourne une erreur si le contexte est annulé
func (m *memoryCache) Clear(ctx context.Context) error {
	if err := ctx.Err(); err != nil {
		return fmt.Errorf("context error in Clear: %w", err)
	}

	m.mu.Lock()
	defer m.mu.Unlock()

	m.items = make(map[string]cache.CacheEntry)
	m.stats = cache.CacheStats{}

	return nil
}

// GetStats retourne les statistiques actuelles du cache.
//
// Paramètres :
// - ctx: Contexte pour la gestion de l'annulation
//
// Retourne les statistiques d'utilisation du cache
func (m *memoryCache) GetStats(ctx context.Context) cache.CacheStats {
	m.mu.RLock()
	defer m.mu.RUnlock()
	return m.stats
}

// Close arrête proprement le cache en arrêtant la routine de nettoyage.
//
// Retourne toujours nil car l'opération ne peut pas échouer
func (m *memoryCache) Close() error {
	close(m.stopChan)
	return nil
}

// startCleanup lance la routine de nettoyage périodique des entrées expirées.
// Cette méthode s'exécute dans une goroutine séparée.
func (m *memoryCache) startCleanup() {
	ticker := time.NewTicker(m.config.CleanupInterval)
	defer ticker.Stop()

	for {
		select {
		case <-ticker.C:
			func() {
				defer func() {
					if r := recover(); r != nil {
						fmt.Printf("Recovered from panic in cleanup: %v\n", r)
					}
				}()
				m.cleanup()
			}()
		case <-m.stopChan:
			return
		}
	}
}

// cleanup effectue le nettoyage des entrées expirées du cache.
// Cette méthode est appelée périodiquement par startCleanup.
func (m *memoryCache) cleanup() {
	m.mu.Lock()
	defer m.mu.Unlock()

	now := time.Now()
	for key, entry := range m.items {
		if now.After(entry.Expiration) {
			m.updateStats(entry.Size, false)
			delete(m.items, key)
		}
	}
}

// updateStats met à jour les statistiques du cache lors de l'ajout ou
// de la suppression d'entrées.
//
// Paramètres :
// - size: Taille de l'entrée en bytes
// - isAdd: true pour un ajout, false pour une suppression
func (m *memoryCache) updateStats(size int64, isAdd bool) {
	if isAdd {
		m.stats.Size += size
		m.stats.ItemCount++
	} else {
		m.stats.Size -= size
		m.stats.ItemCount--
	}
}

// getTTLForType retourne la durée de vie appropriée selon le type de cache.
//
// Paramètres :
// - cacheType: Type de l'entrée
//
// Retourne la durée de vie configurée pour ce type
func (m *memoryCache) getTTLForType(cacheType cache.CacheType) time.Duration {
	switch cacheType {
	case cache.AssistantCache:
		return m.config.AssistantTTL
	case cache.QueryCache:
		return m.config.QueryTTL
	case cache.ModelCache:
		return m.config.ModelTTL
	case cache.UserCache:
		return m.config.UserTTL
	case cache.ConfigCache:
		return m.config.ConfigTTL
	default:
		return m.config.DefaultTTL
	}
}

// calculateSize estime la taille en bytes d'une valeur.
//
// Paramètres :
// - value: Valeur dont on veut estimer la taille
//
// Retourne :
// - La taille estimée en bytes
// - Une erreur si la taille ne peut pas être calculée
func calculateSize(value interface{}) (int64, error) {
	switch v := value.(type) {
	case string:
		return int64(len(v)), nil
	case []byte:
		return int64(len(v)), nil
	case nil:
		return 0, cache.ErrCacheValueInvalid
	default:
		// Estimation par défaut pour les autres types
		// Note: Cette estimation pourrait être améliorée avec une réflexion plus précise
		return 100, nil
	}
}

// Package memory_test contient les tests pour l'implémentation en mémoire du cache.
