// setupTestApp creates a new App instance configured for testing
func setupTestApp(t *testing.T) (*App, string, func()) {
	// Create temporary directory for test files
	tmpDir, err := ioutil.TempDir("", "aiyou-test-*")
	if err != nil {
		t.Fatalf("Failed to create temp directory: %v", err)
	}

	// Create test configuration
	cfg := &config.Config{
		APIEndpoint: "https://api.test.example.com",
		ConfigDir:   tmpDir,
		LogLevel:    "debug",
		MaxThreads:  4,
		Debug:       true,
	}

	// Setup test logger that writes to a buffer
	logger := logrus.New()
	logger.SetOutput(ioutil.Discard) // Suppress logging during tests

	// Create app with test configuration
	app, err := NewApp(&AppConfig{
		Version: "test-version",
		Config:  cfg,
		Logger:  logger,
	})
	if err != nil {
		os.RemoveAll(tmpDir)
		t.Fatalf("Failed to create test app: %v", err)
	}

	// Return cleanup function
	cleanup := func() {
		app.Close()
		if err := os.RemoveAll(tmpDir); err != nil {
			t.Errorf("Failed to cleanup test directory: %v", err)
		}
	}

	return app, tmpDir, cleanup
}

