		expectedOutput string
		setupFunc      func(*testing.T, *App)
	}{
		{
			name:           "version command output",
			args:           []string{"version"},
			expectedOutput: fmt.Sprintf("aiyou CLI version test-version\n"),
		},
		{
			name: "config command output",
			args: []string{"config"},
			expectedOutput: fmt.Sprintf("Configuration:\n API Endpoint: %s\n Log Level: %s\n Max Threads: %d\n Debug Mode: %v\n",
				"https://api.test.example.com", "debug", 4, true),
			setupFunc: func(t *testing.T, a *App) {
				a.SetLoggedIn(true)
			},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			// Créer une nouvelle instance pour chaque test
			app, _, cleanup := setupTestApp(t)
			defer cleanup()

			if tt.setupFunc != nil {
				tt.setupFunc(t, app)
			}

			// Capturer la sortie standard
			oldStdout := os.Stdout
			r, w, _ := os.Pipe()
			os.Stdout = w

			// Exécuter la commande
			app.rootCmd.SetArgs(tt.args)
			err := app.Run(context.Background())
			require.NoError(t, err)

			// Restaurer stdout et lire la sortie capturée
			w.Close()
			os.Stdout = oldStdout
			var buf bytes.Buffer
			_, err = buf.ReadFrom(r)
			require.NoError(t, err)

			// Vérifier la sortie
			assert.Equal(t, tt.expectedOutput, buf.String())
		})
	}
}

