// Package mocks provides test doubles for external dependencies,
// specifically for the aiyou.golib package
package mocks

import (
	"errors"
	"time"
)

var (
	// ErrNotAuthenticated is returned when trying to perform operations without authentication
	ErrNotAuthenticated = errors.New("not authenticated")
	// ErrInvalidCredentials is returned when login fails due to wrong credentials
	ErrInvalidCredentials = errors.New("invalid credentials")
	// ErrTokenExpired is returned when the authentication token has expired
	ErrTokenExpired = errors.New("token expired")
)

// MockClient simulates the behavior of aiyou.golib.Client for testing purposes.
// It provides controlled responses for authentication and token management.
type MockClient struct {
	// AuthenticateFn allows customizing authentication behavior in tests
	AuthenticateFn func(email, password string) error
	// GetTokenFn allows customizing token retrieval behavior in tests
	GetTokenFn func() string
	// RefreshTokenFn allows customizing token refresh behavior in tests
	RefreshTokenFn func() error
	// IsAuthenticatedFn allows customizing authentication status check in tests
	IsAuthenticatedFn func() bool

	// Internal state
	mockToken       string
	isAuthenticated bool
	lastLoginTime   time.Time
}

// NewMockClient creates a new MockClient with default behaviors.
// These defaults can be overridden by setting custom functions after creation.
func NewMockClient() *MockClient {
	return &MockClient{
		AuthenticateFn: func(email, password string) error {
			if email == "" || password == "" {
				return errors.New("email and password are required")
			}
			if email == "test@example.com" && password == "password123" {
				return nil
			}
			return ErrInvalidCredentials
		},
		GetTokenFn: func() string {
			if !m.isAuthenticated {
				return ""
			}
			return "mock-token-123"
		},
		RefreshTokenFn: func() error {
			if !m.isAuthenticated {
				return ErrNotAuthenticated
			}
			return nil
		},
		IsAuthenticatedFn: func() bool {
			return m.isAuthenticated
		},
	}
}

// SetToken implements the aiyou.golib.Client interface by setting a mock token.
// It also updates the authentication state.
func (m *MockClient) SetToken(token string) {
	if token == "" {
		m.isAuthenticated = false
	} else {
		m.isAuthenticated = true
		m.lastLoginTime = time.Now()
	}
	m.mockToken = token
}

// GetToken implements the aiyou.golib.Client interface by returning the current mock token.
// It uses the custom GetTokenFn if provided, otherwise returns the stored mock token.
func (m *MockClient) GetToken() string {
	if m.GetTokenFn != nil {
		return m.GetTokenFn()
	}
	if !m.isAuthenticated {
		return ""
	}
	return m.mockToken
}

// IsAuthenticated returns whether the mock client is currently authenticated
func (m *MockClient) IsAuthenticated() bool {
	if m.IsAuthenticatedFn != nil {
		return m.IsAuthenticatedFn()
	}
	return m.isAuthenticated
}

// Authenticate simulates the authentication process with provided credentials
func (m *MockClient) Authenticate(email, password string) error {
	if m.AuthenticateFn != nil {
		return m.AuthenticateFn(email, password)
	}

	// Default implementation
	if email == "" || password == "" {
		return errors.New("email and password are required")
	}

	// Simulate successful authentication
	if email == "test@example.com" && password == "password123" {
		m.isAuthenticated = true
		m.mockToken = "mock-token-123"
		m.lastLoginTime = time.Now()
		return nil
	}

	return ErrInvalidCredentials
}

// RefreshToken simulates the token refresh process
func (m *MockClient) RefreshToken() error {
	if m.RefreshTokenFn != nil {
		return m.RefreshTokenFn()
	}

	if !m.isAuthenticated {
		return ErrNotAuthenticated
	}

	// Simulate token refresh
	if time.Since(m.lastLoginTime) > 24*time.Hour {
		return ErrTokenExpired
	}

	m.mockToken = "mock-refreshed-token-" + time.Now().Format("20060102150405")
	m.lastLoginTime = time.Now()
	return nil
}

package logger

import (
	"fmt"
	"log"
	"os"
	"time"
)

var (
	debugMode  bool
	silentMode bool
	logger     *log.Logger
)

func init() {
	logger = log.New(os.Stdout, "", 0)
}

func SetDebugMode(debug bool) {
	debugMode = debug
}

func SetSilentMode(silent bool) {
	silentMode = silent
}

func formatMessage(level, message string) string {
	timestamp := time.Now().Format("2006-01-02 15:04:05")
	return fmt.Sprintf("[%s] %s: %s", timestamp, level, message)
}

func Info(message string) {
	if !silentMode {
		logger.Println(formatMessage("INFO", message))
	}
}

func Debug(message string) {
	if debugMode && !silentMode {
		logger.Println(formatMessage("DEBUG", message))
	}
}

func Error(message string) {
	// Errors are always logged, even in silent mode
	logger.Println(formatMessage("ERROR", message))
}

func Warning(message string) {
	if !silentMode {
		logger.Println(formatMessage("WARNING", message))
	}
}
